   $sb26$With spring-boot-starter-webmvc and no extra settings, which port does the embedded Tomcat server listen on?$sb26$,
   $sb27$["80","443","3000","8080"]$sb27$::jsonb,
   3, $sb28$The default port is 8080, and you can change it with server.port in application.properties.$sb28$, 1, 1),
  ('tq-sb-what-is-spring-boot-3', 'pt-sb-what-is-spring-boot',
   $sb29$A @RestController has record Item(String name, int price) {} and the method @GetMapping("/items") List<Item> items() { return List.of(new Item("Pen", 20)); }. What does GET /items return?$sb29$,
   $sb30$["[{\"name\":\"Pen\",\"price\":20}]","Item[name=Pen, price=20]","name=Pen&price=20","An empty page with status 204"]$sb30$::jsonb,
   0, $sb31$Inside a @RestController, Jackson turns the returned list of records into a JSON array.$sb31$, 1, 2),
  ('tq-sb-what-is-spring-boot-4', 'pt-sb-what-is-spring-boot',
   $sb32$The @SpringBootApplication class is in com.shop.app and a @RestController is in com.shop.web. The app starts, but GET /products returns 404. What is the bug?$sb32$,
   $sb33$["The controller method must be static","Port 8080 is blocked by the browser","The controller is outside the package that component scan covers","@RestController only works with XML configuration"]$sb33$::jsonb,
   2, $sb34$@SpringBootApplication scans its own package and the packages below it, and com.shop.web is not under com.shop.app.$sb34$, 1, 3),
  ('tq-sb-what-is-spring-boot-5', 'pt-sb-what-is-spring-boot',
   $sb35$A student pastes import javax.persistence.Entity; from an old blog post into a Spring Boot 4 project. What happens?$sb35$,
   $sb36$["It compiles, because Spring Boot 4 accepts both packages","It fails to compile, because Spring Boot 4 uses jakarta.persistence","Spring Boot rewrites the import automatically at startup","It works, but only on Java 8"]$sb36$::jsonb,
   1, $sb37$Since Spring Boot 3, Spring uses Jakarta EE, so the class now lives in jakarta.persistence and the javax import cannot be found.$sb37$, 1, 4)
on conflict (id) do update set
  question_text = excluded.question_text, options = excluded.options,
  correct_index = excluded.correct_index, explanation = excluded.explanation,
  marks = excluded.marks, sort_order = excluded.sort_order
where (test_questions.question_text, test_questions.options, test_questions.correct_index,
       test_questions.explanation, test_questions.marks, test_questions.sort_order)
  is distinct from (excluded.question_text, excluded.options, excluded.correct_index,
       excluded.explanation, excluded.marks, excluded.sort_order);
delete from public.test_questions where test_id = 'pt-sb-what-is-spring-boot'
  and id <> all (array['tq-sb-what-is-spring-boot-1', 'tq-sb-what-is-spring-boot-2', 'tq-sb-what-is-spring-boot-3', 'tq-sb-what-is-spring-boot-4', 'tq-sb-what-is-spring-boot-5']);

-- ===========================================================================
-- VALIDATION — fail loudly if this batch did not land exactly.
-- ===========================================================================
do $val$
declare
  v_topics int; v_lessons int; v_practice int; v_tests int; v_questions int; v_web boolean; v_mob boolean;
begin
  select count(*) into v_topics from public.learning_topics where source_kind = 'spring_boot_tutorial' and source_ref in ($sb38$getting-started/what-is-spring-boot$sb38$);
  if v_topics <> 1 then raise exception 'validation: expected 1 topics, found %', v_topics; end if;
  select count(*) filter (where c.metadata ->> 'block' = 'lesson'), count(*) filter (where c.metadata ->> 'block' = 'practice')
    into v_lessons, v_practice
    from public.learning_contents c join public.learning_topics t on t.id = c.topic_id
   where c.metadata ->> 'source' = 'spring_boot_seed' and t.source_kind = 'spring_boot_tutorial' and t.source_ref in ($sb38$getting-started/what-is-spring-boot$sb38$);
  if v_lessons <> 1 then raise exception 'validation: expected 1 lesson blocks, found %', v_lessons; end if;
  if v_practice <> 1 then raise exception 'validation: expected 1 practice blocks, found %', v_practice; end if;
  select count(*) into v_tests from public.practice_tests where id in ('pt-sb-what-is-spring-boot') and learning_topic_id is not null;
  if v_tests <> 1 then raise exception 'validation: expected 1 linked mock tests, found %', v_tests; end if;
  select count(*) into v_questions from public.test_questions where test_id in ('pt-sb-what-is-spring-boot');
  if v_questions <> 5 then raise exception 'validation: expected 5 MCQs, found %', v_questions; end if;
  select show_on_website, show_on_mobile into v_web, v_mob from (select id, show_on_website, show_on_mobile from public.learning_grids where lower(slug) = 'spring-boot-tutorial' and source_kind = 'seed' and source_ref = 'spring_boot_tutorial') g;
  raise notice '0130/101 OK: Spring Boot Tutorial batch 01: % topics, % lesson blocks, % practice blocks, % tests, % MCQs. Grid visible on website=%, mobile=%.',
    v_topics, v_lessons, v_practice, v_tests, v_questions, v_web, v_mob;
end
$val$;

notify pgrst, 'reload schema';
